<template><section class="workbench" data-cpf-page="error-recovery-workbench"><header class="header"><div><h1>Error·Unknown Result Workbench</h1><p>Unknown Result, Broker DLQ, Transaction Log Recovery를 조회하고 승인된 사유·Expected Version으로 재처리합니다.</p></div><button :disabled="loading" @click="load">새로고침</button></header><div class="tabs"><div><button v-for="item in ['unknown','dlq','recovery']" :key="item" :class="{primary:tab===item}" @click="tab=item;load()">{{ item }}</button></div><span class="muted">Freshness {{ fetchedAt || '-' }}</span></div><form class="filters" @submit.prevent="load"><label>Status<input v-model.trim="status"></label><label>Transaction ID<input v-model.trim="transactionId"></label><label>Topic<input v-model.trim="topic" :disabled="tab!=='dlq'"></label><button type="submit">조회</button></form><p v-if="error" class="state error">{{ error }}</p><p v-else-if="loading" class="state">조회 중…</p><p v-else-if="!rows.length" class="state">조건에 맞는 오류/복구 대상이 없습니다.</p><div v-if="rows.length" class="table-wrap"><table><thead><tr><th>ID</th><th>상태</th><th>Transaction</th><th>Topic/Target</th><th>Version</th><th>발생 시각</th></tr></thead><tbody><tr v-for="(row,index) in rows" :key="rowId(row,index)" :class="{selected:selected===row}" @click="selected=row"><td>{{ rowId(row,index) }}</td><td>{{ text(row,'status','state') }}</td><td>{{ text(row,'transactionId','transaction_id') }}</td><td>{{ text(row,'topic','target','recoveryTarget') }}</td><td>{{ text(row,'rowVersion','row_version','version','expectedVersion','expected_version') }}</td><td>{{ text(row,'createdAt','created_at','updatedAt','updated_at') }}</td></tr></tbody></table></div><article v-if="tab==='recovery'" class="panel"><div class="header"><h2>File Log Recovery 상태</h2><span class="muted">실제 로그 원장 처리상태</span></div><CpfStructuredData class="detail" :value="fileRecoveryStatus" /></article><article v-if="selected" class="panel"><div class="header"><h2>대상 상세</h2><button v-if="canAct" class="danger" @click="openAction">{{ tab==='unknown'?'결과 확정':tab==='dlq'?'DLQ Replay':'Recovery 실행' }}</button></div><CpfStructuredData class="detail" :value="selected" /></article><div v-if="dialog" class="dialog-backdrop" @click.self="dialog=false"><form class="dialog" @submit.prevent="execute"><h2>위험조치 확인</h2><label v-if="tab==='unknown'">처리<select v-model="action"><option>CONFIRMED_SUCCESS</option><option>CONFIRMED_FAILURE</option><option>RETRY_PENDING</option><option>MANUAL_REVIEW</option><option>RESOLVED</option></select></label><label>Expected Version<input v-model.number="expectedVersion" type="number" min="0" required></label><label>사유<textarea v-model.trim="reason" minlength="10" maxlength="500" required></textarea></label><label class="confirm"><input v-model="confirmed" type="checkbox"> 중복 실행·부분 실패·Audit 영향을 확인했습니다.</label><p v-if="actionError" class="state error">{{ actionError }}</p><div class="actions"><button type="button" @click="dialog=false">취소</button><button class="danger" :disabled="acting||!confirmed||reason.length<10">실행</button></div></form></div><IncidentLifecyclePanel /></section></template>
<script setup lang="ts">import { computed,onMounted,ref } from 'vue';import { useRoute } from 'vue-router';import { findDlq,findFileLogRecoveryStatus,findRecovery,findUnknownResults,replayDlq,resolveUnknown,runRecovery,type JsonMap } from './api';import { errorMessage,read,text } from './support';import { useAdmSessionStore } from '../../stores/admSessionStore';import IncidentLifecyclePanel from './IncidentLifecyclePanel.vue';
const route=useRoute(),session=useAdmSessionStore();const tab=ref<'unknown'|'dlq'|'recovery'>('unknown'),status=ref(''),transactionId=ref(String(route.query.transactionId??'')),topic=ref(''),rows=ref<JsonMap[]>([]),fileRecoveryStatus=ref<JsonMap>({}),selected=ref<JsonMap|null>(null),loading=ref(false),error=ref(''),fetchedAt=ref(''),dialog=ref(false),reason=ref(''),action=ref('MANUAL_REVIEW'),expectedVersion=ref(0),confirmed=ref(false),acting=ref(false),actionError=ref('');const canAct=computed(()=>session.hasButton(tab.value==='unknown'?'RELIABILITY_RESOLVE':tab.value==='dlq'?'RELIABILITY_REPLAY':'RELIABILITY_RECOVERY_RUN'));
function rowId(row:JsonMap,index:number){return String(read(row,'unknownId','unknown_id','messageId','message_id','recoveryEventId','recovery_event_id','id')??index)}async function load(){loading.value=true;error.value='';selected.value=null;try{if(tab.value==='unknown')rows.value=await findUnknownResults(status.value,transactionId.value,100);else if(tab.value==='dlq')rows.value=await findDlq(status.value,transactionId.value,topic.value,100);else{const result=await Promise.all([findRecovery(status.value,100),findFileLogRecoveryStatus()]);rows.value=result[0];fileRecoveryStatus.value=result[1]}fetchedAt.value=new Date().toISOString()}catch(e){rows.value=[];error.value=errorMessage(e)}finally{loading.value=false}}function openAction(){if(!selected.value||!canAct.value)return;expectedVersion.value=Number(read(selected.value,'rowVersion','row_version','version','expectedVersion','expected_version')??0);reason.value='';confirmed.value=false;actionError.value='';dialog.value=true}async function execute(){if(!selected.value||!confirmed.value)return;acting.value=true;actionError.value='';try{if(tab.value==='unknown')await resolveUnknown(rowId(selected.value,0),action.value,reason.value,expectedVersion.value);else if(tab.value==='dlq')await replayDlq(rowId(selected.value,0),reason.value);else await runRecovery(reason.value);dialog.value=false;await load()}catch(e){actionError.value=errorMessage(e)}finally{acting.value=false}}onMounted(load);
</script><style scoped>
.workbench{display:grid;gap:1rem}.header,.actions,.tabs,.pager{display:flex;gap:.65rem;align-items:center;justify-content:space-between;flex-wrap:wrap}.header h1,.header h2{margin:0}.header p{margin:.35rem 0 0;color:#52606d}.filters{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:.7rem;align-items:end}.filters label,.dialog label{display:grid;gap:.3rem}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:.75rem}.card,.panel{border:1px solid #d7dde5;border-radius:.6rem;padding:1rem;background:#fff}.card strong{font-size:1.35rem;display:block}.table-wrap{overflow:auto;border:1px solid #d7dde5;border-radius:.5rem}table{border-collapse:collapse;width:100%;min-width:900px}th,td{padding:.65rem;border-bottom:1px solid #e4e8ed;text-align:left;vertical-align:top}tbody tr{cursor:pointer}tbody tr:hover,tbody tr.selected{background:#f3f6f9}.state{padding:.75rem;border-radius:.4rem;background:#eef3f7}.state.error{background:#fff0f0;color:#a51d1d}.state.warning{background:#fff8dc;color:#715600}.state.success{background:#edf9f0;color:#126b35}.danger{background:#9d1c1c;color:white}.primary{background:#1f5f99;color:white}.detail{white-space:pre-wrap;overflow:auto;max-height:480px;background:#111827;color:#e5e7eb;padding:1rem;border-radius:.5rem}.dialog-backdrop{position:fixed;inset:0;background:#0008;display:grid;place-items:center;z-index:1000}.dialog{width:min(620px,calc(100vw - 2rem));max-height:90vh;overflow:auto;background:#fff;border-radius:.65rem;padding:1.2rem;display:grid;gap:1rem}.dialog textarea{min-height:100px}.confirm{display:flex!important;grid-template-columns:auto 1fr!important;align-items:center}.muted{color:#68737d}.badge{display:inline-block;padding:.15rem .45rem;border-radius:999px;background:#e9eef5}.links{display:flex;gap:.6rem;flex-wrap:wrap}@media(max-width:720px){.header{display:grid}.actions{justify-content:flex-start}}
</style>
